[Form]
public class AVAWHSWorkOverview extends FormRun
{
    boolean activateFilterClicked;

}

/// <summary>
/// init
/// </summary>
public void init()
{
    activateFilterClicked = false;

    super();

    fromDate.dateValue(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));
    toDate.dateValue(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())+10);
    lastGetDataControl.dateTimeValue(DateTimeUtil::utcNow());
}

/// <summary>
/// counterOrders
/// </summary>
public int counterOrders(FormDataSource _formDataSource)
{
    QueryRun queryRun;
    Query query;
    int ret;

    switch (_formDataSource.table())
    {
        case tableNum(AVAOverviewAllWorkPositionsView) :
            query = new Query(_formDataSource.query());
            query.dataSourceTable(tableNum(AVAOverviewAllWorkPositionsView)).addGroupByField(fieldNum(AVAOverviewAllWorkPositionsView,OrderNum));
            break;

        case tableNum(AVAOverviewAllLoadWorkCreatedView) :
            query = new Query(_formDataSource.query());
            query.dataSourceTable(tableNum(AVAOverviewAllLoadWorkCreatedView)).addGroupByField(fieldNum(AVAOverviewAllLoadWorkCreatedView,OrderNum));
            break;

        case tableNum(AVAUtilizationPackagingStationsView) :
            query = new Query(_formDataSource.query());
            query.dataSourceTable(tableNum(AVAUtilizationPackagingStationsView)).addGroupByField(fieldNum(AVAUtilizationPackagingStationsView,OrderNum));
            break;

        case tableNum(AVAUtilizationLoadingLanesView) :
            query = new Query(_formDataSource.query());
            query.dataSourceTable(tableNum(AVAUtilizationLoadingLanesView)).addGroupByField(fieldNum(AVAUtilizationLoadingLanesView,OrderNum));
            break;
    }

    if (query)
    {
        queryRun = new QueryRun(query);
        ret = SysQuery::AVAcountRecordWithRanges(queryRun);
    }

    return ret;
}

/// <summary>
/// counterOrders
