public int numberOfLines(FormDataSource _formDataSource)
{
    QueryRun queryRun;
    queryRun = new QueryRun(_formDataSource.query());
    return SysQuery::AVAcountRecordWithRanges(queryRun);
}

/// <summary>
/// counterOrders
/// </summary>
public real numberOfItemQty(FormDataSource _formDataSource)
{
    QueryRun queryRun;
    Query query;
    real ret;

    switch (_formDataSource.table())
    {
        case tableNum(AVAOverviewAllWorkPositionsView) :
            query = new Query(_formDataSource.query());
            //query.dataSourceTable(tableNum(AVAOverviewAllWorkPositionsView)).addGroupByField(fieldNum(AVAOverviewAllWorkPositionsView,Qty));
            query.dataSourceTable(tableNum(AVAOverviewAllWorkPositionsView)).addSelectionField(fieldNum(AVAOverviewAllWorkPositionsView, Qty), SelectionField::Sum);
            queryRun = new QueryRun(query);
            queryRun.next();
            AVAOverviewAllWorkPositionsView AVAOverviewAllWorkPositionsViewloc = queryRun.get(tableNum(AVAOverviewAllWorkPositionsView));
            ret = AVAOverviewAllWorkPositionsViewloc.Qty;
            break;

        case tableNum(AVAOverviewAllLoadWorkCreatedView) :
            query = new Query(_formDataSource.query());
            //query.dataSourceTable(tableNum(AVAOverviewAllLoadWorkCreatedView)).addGroupByField(fieldNum(AVAOverviewAllLoadWorkCreatedView,Qty));
            break;

        case tableNum(AVAUtilizationPackagingStationsView) :
            query = new Query(_formDataSource.query());
            query.dataSourceTable(tableNum(AVAUtilizationPackagingStationsView)).addSelectionField(fieldNum(AVAUtilizationPackagingStationsView, QtyWork), SelectionField::Sum);
            queryRun = new QueryRun(query);
            queryRun.next();
            AVAUtilizationPackagingStationsView AVAUtilizationPackagingStationsViewloc = queryRun.get(tableNum(AVAUtilizationPackagingStationsView));
            ret = AVAUtilizationPackagingStationsViewloc.QtyWork;
            break;

        case tableNum(AVAUtilizationLoadingLanesView) :
            query = new Query(_formDataSource.query());
            //query.dataSourceTable(tableNum(AVAUtilizationLoadingLanesView)).addGroupByField(fieldNum(AVAUtilizationLoadingLanesView,Qty));
            break;
    }

    return ret;
}

/// <summary>
/// counterOrders
/// </summary>
public real numberOfWeight(FormDataSource _formDataSource)
{
    QueryRun queryRun;
    Query query;
    real ret;

    switch (_formDataSource.table())
    {
        case tableNum(AVAOverviewAllWorkPositionsView) :
            query = new Query(_formDataSource.queryRun().query());
            //query.dataSourceTable(tableNum(AVAOverviewAllWorkPositionsView)).addGroupByField(fieldNum(AVAOverviewAllWorkPositionsView,Qty));
            //query.dataSourceTable(tableNum(AVAOverviewAllWorkPositionsView)).addSelectionField(fieldNum(AVAOverviewAllWorkPositionsView, NetWeight), SelectionField::Sum);
            //query.dataSourceTable(tableNum(AVAOverviewAllWorkPositionsView)).addSelectionField(fieldNum(AVAOverviewAllWorkPositionsView, Qty), SelectionField::Sum);
            queryRun = new QueryRun(query);
            while (queryRun.next())
            {
                AVAOverviewAllWorkPositionsView AVAOverviewAllWorkPositionsViewloc = queryRun.get(tableNum(AVAOverviewAllWorkPositionsView));
                ret += AVAOverviewAllWorkPositionsViewloc.NetWeight * AVAOverviewAllWorkPositionsViewloc.Qty;
            }
            break;

        case tableNum(AVAOverviewAllLoadWorkCreatedView) :
            //query = new Query(_formDataSource.query());
            //query.dataSourceTable(tableNum(AVAOverviewAllLoadWorkCreatedView)).addGroupByField(fieldNum(AVAOverviewAllLoadWorkCreatedView,Qty));
            break;

        case tableNum(AVAUtilizationPackagingStationsView) :
            query = new Query(_formDataSource.queryRun().query());
            //query.dataSourceTable(tableNum(AVAUtilizationPackagingStationsView)).addGroupByField(fieldNum(AVAUtilizationPackagingStationsView,QtyWork));
            //query.dataSourceTable(tableNum(AVAUtilizationPackagingStationsView)).addSelectionField(fieldNum(AVAUtilizationPackagingStationsView, NetWeight), SelectionField::Sum);
            //query.dataSourceTable(tableNum(AVAUtilizationPackagingStationsView)).addSelectionField(fieldNum(AVAUtilizationPackagingStationsView, QtyWork), SelectionField::Sum);
            queryRun = new QueryRun(query);
            while (queryRun.next())
            {
                AVAUtilizationPackagingStationsView AVAUtilizationPackagingStationsViewloc = queryRun.get(tableNum(AVAUtilizationPackagingStationsView));
                ret += AVAUtilizationPackagingStationsViewloc.NetWeight * AVAUtilizationPackagingStationsViewloc.QtyWork;
            }
            break;

        case tableNum(AVAUtilizationLoadingLanesView) :
            query = new Query(_formDataSource.queryRun().query());
            query.dataSourceTable(tableNum(AVAUtilizationLoadingLanesView)).addSelectionField(fieldNum(AVAUtilizationLoadingLanesView, Weight), SelectionField::Sum);
            queryRun = new QueryRun(query);
            queryRun.next();
            AVAUtilizationLoadingLanesView AVAUtilizationLoadingLanesViewLoc = queryRun.get(tableNum(AVAUtilizationLoadingLanesView));
            ret = AVAUtilizationLoadingLanesViewLoc.Weight;
            break;
    }

    return ret;
}

/// <summary>
/// calcHeaderFields
/// </summary>
public void calcHeaderFields(FormDataSource _formDataSource)
{
    reWeightSum.realValue(element.numberOfWeight(_formDataSource));
    ieCounterOrders.value(element.counterOrders(_formDataSource));
    InventQtySum.realValue(element.numberOfItemQty(_formDataSource));
    ieCounter.value(element.numberOfLines(_formDataSource));
}

