/// <summary>
/// init
/// </summary>
public void init()
{
    super();

    SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(AVAOverviewAllWorkPositionsView, WorkStatus))
        .value(queryValue(WHSWorkStatus::Open));  
}

/// <summary>
/// executeQuery
/// </summary>
public void executeQuery()
{
    QueryBuildRange dateRange = SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(AVAOverviewAllWorkPositionsView, LoadSchedShipUTCDateTime));
    dateRange.value(SysQuery::range(fromDate.dateValue(), toDate.dateValue()));

    if (activateFilterClicked)
    {     
        SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(AVAOverviewAllWorkPositionsView, InventLocationId))
        .value(InventLocationIdFilter.text());

        SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(AVAOverviewAllWorkPositionsView, InventSiteId))
        .value(InventSiteIdFilter.text());

        SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(AVAOverviewAllWorkPositionsView, ZoneId))
        .value(WHSZoneIdFilter.text());


    }

    super();

    OverviewAllWorkPositionsTabPage.pageActivated();
}

