/// <summary>
/// displayCrossDocking
/// </summary>
/// <param name = "_AVAOverviewAllLoadWorkCreatedView">AVAOverviewAllLoadWorkCreatedView</param>
/// <returns>NoYesId</returns>
public display NoYesId displayCrossDocking(AVAOverviewAllLoadWorkCreatedView _AVAOverviewAllLoadWorkCreatedView)
{
    WHSLoadLine whsLoadLine;

    select firstonly * from whsLoadLine
        where whsLoadLine.LoadId == _AVAOverviewAllLoadWorkCreatedView.LoadId
        && whsLoadLine.CrossDockQuantity != 0;

    if (whsLoadLine)
    {
        return NoYes::Yes;
    }

    return NoYes::No;
}

/// <summary>
/// executeQuery
/// </summary>
public void executeQuery()
{
    AVAOverviewAllLoadWorkCreatedView AVAOverviewAllLoadWorkCreatedViewloc = AVAOverviewAllLoadWorkCreatedView_ds.cursor();
    QueryBuildRange qbrLoadId = SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(AVAOverviewAllLoadWorkCreatedDetailView, LoadId));

    qbrLoadId.value(AVAOverviewAllLoadWorkCreatedViewloc.LoadId);

    super();
}

/// <summary>
/// display Counter
/// </summary>
/// <param name = "_AVAOverviewAllLoadWorkCreatedDetailView">AVAOverviewAllLoadWorkCreatedDetailView</param>
/// <returns>Counter</returns>
public display Counter displayCounterWorkLine(AVAOverviewAllLoadWorkCreatedDetailView _AVAOverviewAllLoadWorkCreatedDetailView)
{
    WHSWorkLine whsWorkLine;

    select count(RecId) from whsWorkLine
        where whsWorkLine.WorkId == _AVAOverviewAllLoadWorkCreatedDetailView.WorkId
        && whsWorkLine.WorkType == WHSWorkType::Pick;

    return whsWorkLine.RecId;
}

/// <summary>
/// display WHSQtyWork
/// </summary>
/// <param name = "_AVAOverviewAllLoadWorkCreatedDetailView">AVAOverviewAllLoadWorkCreatedDetailView</param>
/// <returns>WHSQtyWork</returns>
public display WHSQtyWork displayQtyWorkLine(AVAOverviewAllLoadWorkCreatedDetailView _AVAOverviewAllLoadWorkCreatedDetailView)
{
    WHSWorkLine whsWorkLine;

    select sum(QtyWork) from whsWorkLine
        where whsWorkLine.WorkId == _AVAOverviewAllLoadWorkCreatedDetailView.WorkId
        && whsWorkLine.WorkType == WHSWorkType::Pick;

    return whsWorkLine.QtyWork;
}

