/// <summary>
/// designed from AVA
/// </summary>
public void init()
{
    super();
    this.query().dataSourceTable(tableNum(WHSWorkTable)).addRange(fieldNum(WHSWorkTable,WorkTransType)).value(SysQuery::value(WHSWorkTransType::CycleCount));

    QueryBuildRange workStatusRange = SysQuery::findOrCreateRange(this.queryBuildDataSource(),fieldNum(WHSWorkTable,WorkStatus));
    workStatusRange.value(strfmt("%1,%2",enum2Str(WHSWorkStatus::Open),enum2Str(WHSWorkStatus::PendingReview)));


    QueryBuildRange dateRange = SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(WHSWorkTable, CreatedDateTime));
    dateRange.value(SysQuery::range(fromDate.dateValue(), toDate.dateValue()));

    if (activateFilterClicked)
    {
        SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(WHSWorkTable, InventLocationId))
        .value(InventLocationIdFilter.text());

        SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(WHSWorkTable, InventSiteId))
        .value(InventSiteIdFilter.text());

        SysQuery::findOrCreateRange(AVAWHSWoklLineGrpWorkLocation_ds.query().dataSourceTable(tableNum(AVAWHSWoklLineGrpWorkLocation)), fieldNum(AVAWHSWoklLineGrpWorkLocation, ZoneId))
        .value(WHSZoneIdFilter.text());
    }
}

/// <summary>
/// N.Freidenberger TASK 14.01.2025 
/// </summary>
public void executeQuery()
{
    QueryBuildRange dateRange = SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(WHSWorkTable, CreatedDateTime));
    dateRange.value(SysQuery::range(fromDate.dateValue(), toDate.dateValue()));

    if (activateFilterClicked)
    {
        if (InventLocationIdFilter.text() != '')
        {
            SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(WHSWorkTable, InventLocationId))
        .value(InventLocationIdFilter.text());
        }

        if (InventSiteIdFilter.text() != '')
        {
            SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(WHSWorkTable, InventSiteId))
        .value(InventSiteIdFilter.text());
        }
        SysQuery::findOrCreateRange(AVAWHSWoklLineGrpWorkLocation_ds.query().dataSourceTable(tableNum(AVAWHSWoklLineGrpWorkLocation)), fieldNum(AVAWHSWoklLineGrpWorkLocation, ZoneId))
        .value(WHSZoneIdFilter.text());

    }    
    super();

}

