/// <summary>
/// clicked
/// </summary>
public void clicked()
{
    activateFilterClicked = true;

    AVAOverviewAllWorkPositionsView_ds.executeQuery();
    AVAOverviewAllLoadWorkCreatedView_ds.executeQuery();
    AVAUtilizationPackagingStationsUnionView_ds.executeQuery();
    AVAUtilizationLoadingLanesView_ds.executeQuery();
    AVAWHSWorkTableCycleCount_ds.executeQuery();

    super();
    activateFilterClicked = false;
}

